package com.fitnutri.backend.submission;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.records.food.*;
import com.fitnutri.backend.records.workout.ExerciseEntryInputs;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class CanonicalEntryHasherV2Test {
 final tools.jackson.databind.ObjectMapper json=new tools.jackson.databind.ObjectMapper();
 final CanonicalEntryHasherV2 hasher=new CanonicalEntryHasherV2(new CanonicalV2Json(json),json,new ZoneResolver("Australia/Sydney"),new FoodEntryInputValidator(new PortionNormalizer()));
 String food(){return "{\"submissionId\":\"11111111-1111-4111-8111-111111111111\",\"recordDate\":\"2026-10-17\",\"zone\":\"Australia/Sydney\",\"source\":\"MANUAL\",\"previewFingerprint\":\""+"f".repeat(64)+"\",\"entries\":[{\"kind\":\"SINGLE\",\"clientEntryId\":\"22222222-2222-4222-8222-222222222222\",\"referenceId\":\"101\",\"quantityGrams\":100,\"mealType\":\"LUNCH\"}]}";}
 CanonicalEntryHasherV2.Submission food(String value){return hasher.food(json.readValue(value,FoodEntryInputs.BatchRequest.class));}
 @Test void foodDecimalsDefaultsAndIndependentGoldenVector(){var first=food(food());assertEquals(first.requestSha256(),food(food().replace("\"quantityGrams\":100","\"quantityGrams\":100.000")).requestSha256());assertEquals(first.requestSha256(),food(food().replace("\"mealType\":\"LUNCH\"","\"selectionKind\":\"USER_SELECTED\",\"searchMetadataRevision\":null,\"mealType\":\"LUNCH\"")).requestSha256());assertNotEquals(first.requestSha256(),food(food().replace("LUNCH","DINNER")).requestSha256());assertEquals("eb663a7b77206192cc6ea54bc7aff76aa06da4f3862a32b2c069f209cceacb70",first.requestSha256());assertEquals(1,first.allEntryIds().size());}
 @Test void rootAndLeafMembershipAndArrayOrderAreInputs(){String entry="{\"kind\":\"SINGLE\",\"clientEntryId\":\"33333333-3333-4333-8333-333333333333\",\"referenceId\":\"101\",\"quantityGrams\":100,\"mealType\":\"LUNCH\"}";String two=food().replace("}]}","},"+entry+"]}");var node=json.readTree(two);var reversed=node.deepCopy();var array=(tools.jackson.databind.node.ArrayNode)reversed.get("entries");var first=array.remove(0);array.add(first);assertNotEquals(food(two).requestSha256(),food(json.writeValueAsString(reversed)).requestSha256());assertThrows(BusinessException.class,()->food(two.replace("33333333-3333-4333-8333-333333333333","22222222-2222-4222-8222-222222222222")));}
 String exercise(){return "{\"submissionId\":\"11111111-1111-4111-8111-111111111111\",\"recordDate\":\"2026-10-17\",\"zone\":\"Australia/Sydney\",\"source\":\"MANUAL\",\"previewFingerprint\":\""+"f".repeat(64)+"\",\"entry\":{\"kind\":\"QUICK\",\"clientEntryId\":\"22222222-2222-4222-8222-222222222222\",\"period\":{\"clientEntryId\":\"22222222-2222-4222-8222-222222222222\",\"periodKind\":\"ACTIVITY\",\"optionId\":\"201\",\"durationMinutes\":20,\"equipmentDetails\":{},\"movements\":[],\"calculationFingerprint\":\""+"e".repeat(64)+"\"}}}";}
 @Test void quickSharedIdentityEmptyDetailsAndExactMinutesAreCanonical(){var a=hasher.exercise(json.readValue(exercise(),ExerciseEntryInputs.CreateRequest.class));var b=hasher.exercise(json.readValue(exercise().replace("\"equipmentDetails\":{}","\"equipmentDetails\":{\"speedKmh\":null}").replace("\"durationMinutes\":20","\"durationMinutes\":20.00"),ExerciseEntryInputs.CreateRequest.class));assertEquals(a.requestSha256(),b.requestSha256());assertEquals(1,a.allEntryIds().size());assertNotEquals(a.requestSha256(),food(food()).requestSha256());assertThrows(BusinessException.class,()->hasher.exercise(json.readValue(exercise().replace("\"durationMinutes\":20","\"durationMinutes\":20.001"),ExerciseEntryInputs.CreateRequest.class)));assertThrows(BusinessException.class,()->hasher.exercise(json.readValue(exercise().replace("\"equipmentDetails\":{}","\"equipmentDetails\":{\"met\":5}"),ExerciseEntryInputs.CreateRequest.class)));}
 @Test void workoutOptionalTitleMovementDetailsOriginsAndPeriodOrderAreHashed(){
  var period=new ExerciseEntryInputs.Period(UUID.randomUUID(),"STRENGTH","201",new java.math.BigDecimal("50"),Map.of(),List.of(new ExerciseEntryInputs.Movement("301",3L,8L,new java.math.BigDecimal("40"))),"e".repeat(64));var root=UUID.randomUUID();var submission=UUID.randomUUID();var date=java.time.LocalDate.of(2020,1,1);
  var request=new ExerciseEntryInputs.CreateRequest(submission,date,"Australia/Sydney",com.fitnutri.backend.records.RecordSource.MANUAL,"f".repeat(64),new ExerciseEntryInputs.Workout(root,null,List.of(period),null));var first=hasher.exercise(request);
  var explicitTitle=new ExerciseEntryInputs.CreateRequest(submission,date,request.zone(),request.source(),request.previewFingerprint(),new ExerciseEntryInputs.Workout(root,"Gym workout",List.of(period),null));assertEquals(first.requestSha256(),hasher.exercise(explicitTitle).requestSha256());
  var origin=new ExerciseEntryInputs.CreateRequest(submission,date,request.zone(),request.source(),request.previewFingerprint(),new ExerciseEntryInputs.Workout(root,null,List.of(period),"999"));assertNotEquals(first.requestSha256(),hasher.exercise(origin).requestSha256());
  var changed=new ExerciseEntryInputs.Period(period.clientEntryId(),"STRENGTH","201",period.durationMinutes(),Map.of(),List.of(new ExerciseEntryInputs.Movement("301",3L,8L,new java.math.BigDecimal("41"))),period.calculationFingerprint());assertNotEquals(first.requestSha256(),hasher.exercise(new ExerciseEntryInputs.CreateRequest(submission,date,request.zone(),request.source(),request.previewFingerprint(),new ExerciseEntryInputs.Workout(root,null,List.of(changed),null))).requestSha256());
  assertThrows(BusinessException.class,()->hasher.exercise(new ExerciseEntryInputs.CreateRequest(submission,date,request.zone(),request.source(),request.previewFingerprint(),new ExerciseEntryInputs.Workout(root,null,List.of(period,period),null))));
 }
}
